    "q": "HRT per p5?",
    "a": "Source: only approved for severe perimenopausal vasomotor symptoms (hot flashes, urge incontinence, atrophic vaginitis), not to preserve bone density or for mood/cognition, since more estrogen exposure raises risk of breast cancer, MI, and thromboembolism (estrogen upregulates fibrinogen and factors V and VIII).",
